const allocItems = input.items.filter((i) => ALLOCATION_CATEGORIES.has(i.category) && i.outputWeight > 0);
...
// :109-113 —— 只有 netPool<=0 或 ΣV<=0 才 warning；allocItems 为空时什么都不加
if (allocItems.length > 0 && netPool <= 0) { ... } else if (allocItems.length > 0 && totalValue <= 0) { ... }
else if (allocItems.length > 0) { /* 分摊 */ }
```
```ts
// :333-345 —— 即使 allocations=[]、warnings=[]，也照常 create 快照
const version = (await prisma.costAllocationRun.count({ where: { batchPrefix: prefix } })) + 1;
return prisma.costAllocationRun.create({ data: { ..., netPool: result.pool.netPool, warnings: JSON.stringify(result.warnings), lines: { create: [...] } } });
```

**问题描述**
当该批 `poolAmount > 0` 但既无 `SplitProductInboundRecord` 也无 GRADE 直销（`allocItems.length === 0`）时：`allocations = []`、`warnings = []`，快照照常落库（`poolAmount>0, netPool>0, 无 ALLOCATION 行`），`/close` 还返回非空 `costSnapshotVersion`（carcass.ts:746-749），前端会误认为分摊成功。随后 `buildUnitValueMap` 对该批没有任何单位成本 → 盘点差异金额（carcass.ts:1059-1077）与销售毛利静默缺成本。这与 spec §5.4「必须带 warning，不再静默」的口径精神不符。

**触发场景**
最典型：打级完成后**先封批、后补分割入库**（封批后 `/split-inbound/submit` 被 400 拦住）→ 封批那一刻成品入库为 0，自动快照 pool 有值、Σ分摊=0、无告警；即使事后解封重封产生 v2，v1 仍留在历史里且当时无任何提示。同理「打级全作废后封批」「纯空批次封批」也是静默 0 成本快照。

**建议**
- `allocItems.length === 0 && netPool > 0` 时 push 一条 warning（如「该批无分摊对象（成品入库/直销均为 0），成本未分摊」），并让其进 `CostAllocationRun.warnings` 与封批响应；
- 空批次（无打级记录）封批时最好在 `/close` 响应里给 `warning`，或直接拒绝（需业务确认）；
- 可考虑 `netPool>0 && allocations.length===0` 时不计入「最新快照」，避免 `buildUnitValueMap` 取到空快照遮蔽更早的有效快照。

