    //（code 序列不变），只比 code 会早退不掉，VisibleItems 保留旧实例 → 卡片与 InboundItems 脱钩
    //（选中高亮/默认皮重读到的是旧对象）。
    var unchanged = visible.Count == VisibleItems.Count &&
                    visible.Zip(VisibleItems, (fresh, current) => ReferenceEquals(fresh, current))
                        .All(same => same);
    if (!unchanged)
    {
        VisibleItems.Clear();
        foreach (var item in visible) VisibleItems.Add(item);
