private void RefreshVisibleItems()
{
    var visible = _favorites.Filter(InboundItems, i => i.Code, SelectedItemCode);
    // 集合内容与实例引用都未变时不动 UI（避免选中卡片被无谓重建）。
    // FC-10：必须比实例引用（与 Stocktake 的 M18 修复同构）——重载字典会重建 InboundItems 实例
    //（code 序列不变），只比 code 会早退不掉，VisibleItems 保留旧实例 → 卡片与 InboundItems 脱钩
    //（选中高亮/默认皮重读到的是旧对象）。
    var unchanged = visible.Count == VisibleItems.Count &&
                    visible.Zip(VisibleItems, (fresh, current) => ReferenceEquals(fresh, current))
                        .All(same => same);
    if (!unchanged)
    {
        VisibleItems.Clear();
        foreach (var item in visible) VisibleItems.Add(item);
    }

    // M11 / FC-10：零交集已自动落回「全部」→ 列表重填后提示一次（同次进场不重复刷）
    NotifyFavoritesFallbackIfPending();
}
```
