/// 第 1 次重试用于前缀权威切换（FC-14），第 2 次用于权威前缀下的血码撞号对齐；
/// 两次后仍 409 即按永久失败进「需处理」，硬上限防止异常响应导致死循环。
private const int MaxConflictRetries = 2;
