        break;
    response = await _httpClient.PostAsJsonAsync(url, BuildSubmitRequest(record));
    responseContent = await response.Content.ReadAsStringAsync();
}
```

**③ 单轮自愈** — [:284-314](scale-net/src/ScaleApp.Infrastructure/Services/GradingSyncService.cs#L284-L314)：前缀优先（同返 `nextBloodCode` 一并采用），否则撞号通道；旧格式记录返 false（不做半截改写）

```csharp
if (authoritativePrefix 非空且与当前前缀不同) {
    if (await TryApplyAuthoritativeBatchPrefixAsync(record, authoritativePrefix!, nextBloodCode)) return true;
    return false;                      // 反推不出前缀：交人工，避免 400 死锁
}
if (nextBloodCode 非空且与当前血码不同) {
    record.BloodCode = nextBloodCode!;
    record.IdempotencyKey = $"{record.BatchNo}-{nextBloodCode}-{record.SerialNo}";
    await _gradingRepo.UpdatePendingBloodCodeAsync(record.Id, nextBloodCode!);
    return true;
}
return false;
```

幂等键每段改写：段 1 = `UpdateAsync` 落新批号 → `UpdatePendingBloodCodeAsync` 按库中新 BatchNo 重算键；段 2 = 只改血码+键。前缀事件仅段 1 触发一次。

